/**
 * ISEF affiliated-fair dataset — types + thin JSON wrapper (DAT-2).
 *
 * The data itself lives in `dataset.json`, auto-generated by
 * `scripts/scrape-isef-fairs.mjs` from findafair.societyforscience.org
 * (266 fairs; dates confirmed from the Society directory, coordinates
 * geocoded from fair city via Nominatim). Re-run the script each fall when
 * fairs complete annual affiliation — it emits JSON directly, so tsc never
 * re-parses ~3,700 lines of literals on every build.
 */

import FAIRS_DATA from './dataset.json'

export type SeedFairLevel = 'international' | 'state' | 'regional'

export interface SeedFair {
  key: string
  name: string
  level: SeedFairLevel
  state: string | null
  websiteUrl: string
  latitude: number
  longitude: number
  parentKey?: string
  year: number
  eventDate?: string
  registrationDeadline?: string
  abstractDeadline?: string
  status: 'confirmed' | 'estimated'
}

export const FAIRS = FAIRS_DATA as SeedFair[]
